34	fn bytes_unescape(body: &str, line: usize) -> Result<String, (usize, String)> {
35	    let cs: Vec<char> = body.chars().collect();
36	    let mut pre = String::new();
37	    let mut i = 0;
38	    while i < cs.len() {
39	        if cs[i] == '\\' && i + 1 < cs.len() {
40	            if matches!(cs[i + 1], 'u' | 'U' | 'N') {
41	                pre.push_str("\\\\");
42	            } else {
43	                pre.push('\\');
44	            }
45	            pre.push(cs[i + 1]);
46	            i += 2;
47	            continue;
48	        }
49	        pre.push(cs[i]);
50	        i += 1;
51	    }
52	    let v = unescape(&pre, line)?;
53	    Ok(v.chars().map(|c| char::from_u32(c as u32 & 0xff).unwrap()).collect())
