70	            '\n' => {}
71	            '\\' => out.push('\\'),
72	            '\'' => out.push('\''),
73	            '"' => out.push('"'),
74	            'n' => out.push('\n'),
75	            't' => out.push('\t'),
76	            'r' => out.push('\r'),
77	            'a' => out.push('\x07'),
78	            'b' => out.push('\x08'),
79	            'f' => out.push('\x0c'),
