// run(stmt, params, db, begin, row): reset, bind a tuple or list of None / int / float / str / bytes and
// step, all in one call. begin is the implicit "BEGIN ..." to run first when the connection is in autocommit
// (CPython's legacy isolation_level); row 1 also reads the first row (text columns as bytes, with the column
// kinds alongside) so a point query needs no fetch call. Returns the result code, the column count, names and
// declared types, the connection's changes and last insert rowid, the first row and the column kinds
// (5 null, 1 int, 2 float, 3 text, 4 blob). The result code is -1 when the parameters need Python (a dict,
// other types, a count that is off).

// None: ok (the caller steps on). Some(rc): the implicit BEGIN could not be prepared or stepped.
fn fast_begin(o: &SqlOps, db: i64, begin: Option<&str>) -> Option<i64> {
    let begin = begin?;
    if (o.db_int)(db, 3) == 0 {
        return None;
    }
    let (rc, bst, _used) = (o.prepare)(db, begin.as_bytes());
    if rc != 0 {
        return Some(rc);
    }
    if bst != 0 {
        let rc = (o.step)(bst);
        (o.finalize)(bst);
        if rc != 100 && rc != 101 {
            return Some(rc);
        }
    }
    None
}

fn fast_param(v: &V) -> bool {
    matches!(v, V::None | V::Int(_) | V::Float(_) | V::Str(_))
        || matches!(v, V::Ext(x) if x.any().is::<BytesV>())
}

// None: the parameters need Python. Some(rc): the statement was reset, bound and stepped.
fn fast_step(o: &SqlOps, stmt: i64, ps: &[V]) -> Option<i64> {
    if ps.len() as i64 != (o.nparams)(stmt) || ps.iter().any(|v| !fast_param(v)) {
        return None;
    }
    (o.reset)(stmt);
    for (k, v) in ps.iter().enumerate() {
        if (o.bind)(stmt, k as i64 + 1, v) != 0 {
            return None;
        }
    }
    Some((o.step)(stmt))
}

#[allow(clippy::type_complexity)]
fn run_fast(o: &SqlOps, stmt: i64, db: i64, ps: &[V], begin: Option<&str>, row: i64)
    -> (i64, i64, Vec<V>, Vec<V>, i64, i64, Vec<V>, Vec<V>) {
    let none = || (-1, 0, vec![], vec![], 0, 0, vec![], vec![]);
    if let Some(rc) = fast_begin(o, db, begin) {
        return (rc, 0, vec![], vec![], 0, 0, vec![], vec![]);
    }
    let rc = match fast_step(o, stmt, ps) {
        Some(rc) => rc,
        None => return none(),
    };
    let nc = if rc == 100 || rc == 101 { (o.ncols)(stmt) } else { 0 };
    let mut names = Vec::with_capacity(nc as usize);
    let mut decls = Vec::with_capacity(nc as usize);
    for k in 0..nc {
        names.push(st(String::from_utf8_lossy(&(o.col_name)(stmt, k)).into_owned()));
        decls.push((o.col_decl)(stmt, k).map_or(V::None, st));
    }
    let mut first = vec![];
    let mut kinds = vec![];
    if row == 1 && rc == 100 {
        first = Vec::with_capacity(nc as usize);
        kinds = Vec::with_capacity(nc as usize);
        for k in 0..nc {
            let d = (o.col)(stmt, k);
            kinds.push(V::Int(match d {
                DbV::Null => 5,
                DbV::Int(_) => 1,
                DbV::Float(_) => 2,
                DbV::Text(_) => 3,
                DbV::Blob(_) => 4,
            }));
            first.push(dbv_py(d, 0).unwrap_or(V::None));
        }
    }
