        if not fresh:
            self._desc_meta = None
            self._conv = None
    else:
        begin = None
        pre = not con._detect and con.text_factory is str
        if not fresh:
            self._desc_meta = None
            self._conv = None
            self.rowcount = -1
    if not stmt.st:
