    for i in range(n):
        _s.exec(st.st, (i % 1000,), con._db, None, 1, 1)
def full():
    s = 0.0
    for i in range(n):
        r = con.execute("select name, v from t where id = ?", (i % 1000,)).fetchone()
        s += r[1]
    return s
def best(f, k=3):
    ts = []
    for _ in range(k):
        t = time.perf_counter(); f(); ts.append(time.perf_counter()-t)
    return min(ts)
