import sqlite3, time
n = 100000
con = sqlite3.connect(":memory:")
con.execute("create table t (id integer primary key, name text, v real)")
for i in range(1000):
    con.execute("insert into t values (?, ?, ?)", (i, "n%d" % i, i * 0.25))
st = con._statement("select name, v from t where id = ?")
def engine_only():
    s = 0.0
    for i in range(n):
        rc, rc2, nc, ch, lr, row, raw, kinds, bad = st._s_exec(7, (i % 1000,))
        s += row[0] if isinstance(row[0], str) else 0
    return s
# measure direct glue call via _s.exec
import _brevi_sqlite as _s
def glue_only():
    for i in range(n):
        _s.exec(st.st, (i % 1000,), con._db, None, 1, 1)
def full():
    s = 0.0
    for i in range(n):
        r = con.execute("select name, v from t where id = ?", (i % 1000,)).fetchone()
        s += r[1]
    return s
def best(f, k=3):
    ts = []
    for _ in range(k):
        t = time.perf_counter(); f(); ts.append(time.perf_counter()-t)
    return min(ts)
print("glue", best(glue_only))
print("full", best(full))

