# the single execute fast path: no executemany and no adapters, so one engine call does the implicit
# BEGIN (when needed), reset, bind and step, and returns the columns and counts. For a SELECT with the
# default text factory it also reads the first row and steps again, so execute(...).fetchone() is one
# engine call. fresh: the cursor is new from Connection.execute, so nothing to release or clear.
def _fast_query(self, sql, params, fresh):
    self._fresh = False
    if fresh:
        con = self.connection
    else:
        if self._closed:
            raise ProgrammingError("Cannot operate on a closed cursor.")
        con = self.connection
        if not con._db:
            raise ProgrammingError("Cannot operate on a closed database.")
        if self._stmt is not None:
            self._stmt.release()
            self._stmt = None
        if self._pre is not None:
            self._pre = None
    stmt = con._statement(sql)

